    h, w = len(out), len(out[0])
    for c in range(w):
        # A bottom 5 marker establishes a vertical beam; color is the nearest
        # nonzero object along the beam, propagating outward from each object.
        if out[h-1][c] == 5:
            for r in range(h-2, -1, -1):
